/* Scale tokens: type, spacing, radius, shadow, motion, layout. Use these in new CSS. */
:root {
  --font-sans: 'Inter', sans-serif;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --text-xs: 0.75rem;   /* 12px */
  --text-sm: 0.875rem;  /* 14px */
  --text-base: 1rem;    /* 16px */
  --text-lg: 1.125rem;  /* 18px */
  --text-xl: 1.25rem;   /* 20px */
  --text-2xl: 1.5rem;   /* 24px */
  --text-3xl: 1.875rem; /* 30px */
  --text-4xl: 2.25rem;  /* 36px */
  --leading-tight: 1.25;
  --leading-snug: 1.375;
  --leading-normal: 1.5;
  --leading-relaxed: 1.625;
  --spacing: 0.25rem;   /* 1 step; space N = calc(var(--spacing) * N) */
  --radius-sm: 0.25rem;
  --radius-md: 0.375rem;
  --radius-lg: 0.5rem;
  --radius-xl: 0.75rem;
  --radius-2xl: 1rem;
  --radius-3xl: 1.5rem;
  --radius-full: 9999px;
  --shadow-xs: 0 1px 2px 0 var(--c-000000-a5);
  --shadow-sm: 0 1px 3px 0 var(--c-000000-a10), 0 1px 2px -1px var(--c-000000-a10);
  --shadow-md: 0 4px 6px -1px var(--c-000000-a10), 0 2px 4px -2px var(--c-000000-a10);
  --shadow-lg: 0 10px 15px -3px var(--c-000000-a10), 0 4px 6px -4px var(--c-000000-a10);
  --shadow-xl: 0 20px 25px -5px var(--c-000000-a10), 0 8px 10px -6px var(--c-000000-a10);
  --ease: cubic-bezier(0.4, 0, 0.2, 1);
  --duration: 150ms;
  --default-transition-duration: 150ms;
  --default-transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  --container: 1260px;
}
