  }

  .t-text { color: var(--theme-text); }
  .t-muted { color: var(--theme-text-muted); }
  .t-subtle { color: var(--theme-text-subtle); }
  .t-strong { color: var(--theme-primary-dark); }
  .t-ink { color: var(--theme-heading); }
  .t-accent { color: var(--theme-primary); }
  .t-light { color: var(--theme-primary-light); }
  .t-white { color: var(--theme-white); }
  .t-orange { color: var(--theme-accent); }
  .t-warning { color: var(--theme-warning); }
  .t-danger { color: var(--theme-danger); }

  .fw-normal { font-weight: 400; }
  .fw-medium { font-weight: 500; }
  .fw-semibold { font-weight: 600; }
  .fw-bold { font-weight: 700; }
  .fw-extrabold { font-weight: 800; }

